Here is a debounce function written in JavaScript.

```javascript
function debounce(func, delay) {
  let timeoutId;
  return function(...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
      func.apply(this, args);
    }, delay);
  };
}

// Example usage:
function logInput(text) {
  console.log("API call triggered with:", text);
}

const debouncedLog = debounce(logInput, 500);

// Simulate rapid input events
// debouncedLog("a");
// debouncedLog("ab");
// debouncedLog("abc");
```

```c
void reverseString(char *str) {
    if (str == NULL) {
        return;
    }

    int left = 0;
    int right = strlen(str) - 1;

    while (left < right) {
        // Swap characters
        char temp = str[left];
        str[left] = str[right];
        str[right] = temp;

        // Move pointers
        left++;
        right--;
    }
}
```

```javascript
function capitalizeWords(sentence) {
  if (!sentence) {
    return "";
  }
  return sentence.toLowerCase().split(' ')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}
```

```java
public class StringUtils {
    public static int countVowels(String text) {
        if (text == null) {
            return 0;
        }

        int vowelCount = 0;
        String lowerCaseText = text.toLowerCase();
        String vowels = "aeiou";

        for (int i = 0; i < lowerCaseText.length(); i++) {
            char ch = lowerCaseText.charAt(i);
            if (vowels.indexOf(ch) != -1) {
                vowelCount++;
            }
        }

        return vowelCount;
    }
}
